/* ============================================================
   ABSENSI & NILAI — fitur tambahan: Download PDF
   (Rekap Kehadiran & Nilai + Jurnal Guru)

   File ini BERJALAN SETELAH absensi.js pada halaman yang sama,
   sehingga bisa langsung memakai variabel/fungsi yang sudah ada
   di absensi.js: state, TP_LIST, BULAN_NAMA, NAMA_BULAN_ID,
   tanggalIndonesiaHariIni(), escapeHtml().

   CARA PASANG:
   1. Upload file ini (absensi-pdf.js) ke folder yang sama dengan
      absensi.js di repo GitHub kamu.
   2. Di absensi.html, tambahkan SATU baris ini tepat SETELAH
      baris <script src="absensi.js"></script> dan sebelum </body>:

        <script src="absensi-pdf.js"></script>

   Setelah itu tombol "Download PDF" otomatis muncul di sebelah
   tombol "Download Excel" (tab Rekap) dan "Download Excel (A4)"
   (tab Jurnal Guru) di Panel Admin.

   Kalau suatu saat mau ganti gambar tanda tangan/stempel, tinggal
   ganti nilai KEPALA_IMG_B64 / GURU_IMG_B64 di bawah ini dengan
   base64 JPEG gambar baru (background putih, tanpa transparansi).
   ============================================================ */

(function(){

  // ---- Gambar TTD & Stempel Kepala Madrasah + TTD Guru (JPEG base64, background putih) ----
  const KEPALA_IMG_B64 = "";
  const GURU_IMG_B64   = "";
  const KEPALA_IMG_RATIO = 420/344; // lebar/tinggi gambar asli
  const GURU_IMG_RATIO   = 420/344;

  const MATA_PELAJARAN = "Bahasa Arab"; // sesuaikan kalau nama mapel berubah

  // ---------------- Loader jsPDF (lazy, hanya diambil saat tombol PDF dipakai) ----------------
  let jsPdfReady = null;
  function loadScriptTag(src){
    return new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = src;
      s.onload = resolve;
      s.onerror = () => reject(new Error('Gagal memuat ' + src));
      document.head.appendChild(s);
    });
  }
  function pastikanJsPDF(){
    if(jsPdfReady) return jsPdfReady;
    jsPdfReady = (async () => {
      if(!(window.jspdf && window.jspdf.jsPDF)){
        await loadScriptTag('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js');
      }
      if(!(window.jspdf && window.jspdf.jsPDF && window.jspdf.jsPDF.API && window.jspdf.jsPDF.API.autoTable)){
        await loadScriptTag('https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.2/jspdf.plugin.autotable.min.js');
      }
    })();
    return jsPdfReady;
  }

  // ---------------- Util ----------------
  const ARABIC_RE = /[\u0600-\u06FF\u0750-\u077F]+/g;
  function bersihkanTeksPdf(v){
    if(v === null || v === undefined) return '';
    let t = String(v).replace(ARABIC_RE, '').replace(/\s{2,}/g, ' ').trim();
    return t;
  }

  function namaFileAman(s){
    return String(s || '').replace(/[^\w\-]+/g, '_');
  }

  // ---------------- Blok tanda tangan (dipakai di kedua jenis PDF) ----------------
  // Meniru layout: judul jabatan (2 baris) -> gambar TTD/stempel -> nama (garis bawah) -> NIP,
  // dengan baris "nama" & "NIP" dua kolom selalu sejajar meskipun tinggi gambar beda (rata bawah).
  function tinggiBlokTtd(doc, imgH){
    const titleLineH = 4.3, gapTitleImg = 1.2, gapImgName = 1.8, nameLineH = 4.6, gapNameNip = 1.1, nipLineH = 4;
    return (titleLineH*2) + gapTitleImg + imgH + gapImgName + nameLineH + gapNameNip + nipLineH;
  }

  function gambarBlokTtd(doc, opts){
    // opts: centerX, titleLines[2], imgB64, imgW, imgH, name, nip, commonBottomY
    const titleLineH = 4.3, gapTitleImg = 1.2, gapImgName = 1.8, nameLineH = 4.6, gapNameNip = 1.1, nipLineH = 4;

    let y = opts.commonBottomY; // baseline baris NIP
    doc.setFont('helvetica','normal'); doc.setFontSize(9.5);
    doc.text(opts.nip, opts.centerX, y, {align:'center'});

    y -= (gapNameNip + nameLineH*0.15); // sedikit naik ke baseline nama
    const nameY = y - (nameLineH*0.65);
    doc.setFont('helvetica','bold'); doc.setFontSize(10.5);
    doc.text(opts.name, opts.centerX, nameY, {align:'center'});
    const nameWidth = doc.getTextWidth(opts.name);
    doc.setLineWidth(0.25);
    doc.line(opts.centerX - nameWidth/2, nameY + 1.1, opts.centerX + nameWidth/2, nameY + 1.1);

    const imgBottomY = nameY - (nameLineH*0.35) - gapImgName;
    const imgTopY = imgBottomY - opts.imgH;
    doc.addImage(opts.imgB64, 'JPEG', opts.centerX - opts.imgW/2, imgTopY, opts.imgW, opts.imgH);

    const titleBottomY = imgTopY - gapTitleImg;
    doc.setFont('helvetica','normal'); doc.setFontSize(10);
    doc.text(opts.titleLines[1], opts.centerX, titleBottomY, {align:'center'});
    doc.text(opts.titleLines[0], opts.centerX, titleBottomY - titleLineH, {align:'center'});

    return titleBottomY - titleLineH; // y paling atas blok ini (untuk cek muat halaman)
  }

  function tambahBlokTandaTangan(doc, startY){
    const pageW = doc.internal.pageSize.getWidth();
    const pageH = doc.internal.pageSize.getHeight();
    const marginX = 14;

    const namaGuru = (state.pengaturanGuru && state.pengaturanGuru.namaGuru) || 'Antung Sobri Fattah, S.Ag.';
    const nipGuru = (state.pengaturanGuru && state.pengaturanGuru.nipGuru) || 'NIP. 197402222003121002';
    const namaKamad = (state.pengaturanSekolah && state.pengaturanSekolah.namaKamad) || 'Roihanun, S.Pd., M.Pd.';
    const nipKamad = (state.pengaturanSekolah && state.pengaturanSekolah.nipKamad) || 'NIP. 196812011992032001';
    const kota = (state.pengaturanSekolah && state.pengaturanSekolah.kota) || 'Balikpapan';

    const imgKepalaW = 25.6, imgKepalaH = imgKepalaW / KEPALA_IMG_RATIO;
    const imgGuruW = 17.5, imgGuruH = imgGuruW / GURU_IMG_RATIO;

    const tinggiKepala = tinggiBlokTtd(doc, imgKepalaH);
    const tinggiGuru = tinggiBlokTtd(doc, imgGuruH);
    const tinggiMaks = Math.max(tinggiKepala, tinggiGuru);
    const tinggiTotalDibutuhkan = 8 + tinggiMaks; // + baris tanggal di atas

    if(startY + tinggiTotalDibutuhkan > pageH - 12){
      doc.addPage(doc.internal.pageSize.getWidth() > doc.internal.pageSize.getHeight() ? 'l' : 'p');
      startY = 18;
    }

    doc.setFont('helvetica','normal'); doc.setFontSize(10);
    doc.text(`${kota}, ${tanggalIndonesiaHariIni(kota).split(', ')[1] || ''}`, pageW - marginX, startY, {align:'right'});

    const blockTop = startY + 7;
    const commonBottomY = blockTop + tinggiMaks;

    const contentW = pageW - marginX*2;
    const colW = contentW / 2;
    const centerXKiri = marginX + colW/2;
    const centerXKanan = marginX + colW + colW/2;

    gambarBlokTtd(doc, {
      centerX: centerXKiri,
      titleLines: ['Mengetahui,', 'Kepala Madrasah,'],
      imgB64: 'data:image/jpeg;base64,' + KEPALA_IMG_B64,
      imgW: imgKepalaW, imgH: imgKepalaH,
      name: namaKamad, nip: nipKamad,
      commonBottomY
    });
    gambarBlokTtd(doc, {
      centerX: centerXKanan,
      titleLines: ['Guru Mata Pelajaran,', MATA_PELAJARAN + ','],
      imgB64: 'data:image/jpeg;base64,' + GURU_IMG_B64,
      imgW: imgGuruW, imgH: imgGuruH,
      name: namaGuru, nip: nipGuru,
      commonBottomY
    });
  }

  // ---------------- PDF: Rekap Kehadiran & Nilai ----------------
  async function generatePdfRekap(){
    const r = state.lastRekap;
    if(!r){ alert('Pilih kelas dan tunggu rekap termuat dahulu, baru download PDF.'); return; }
    const btn = document.getElementById('btnDownloadRekapPdf');
    if(btn){ btn.disabled = true; btn.textContent = 'Menyiapkan PDF…'; }
    try{
      await pastikanJsPDF();
      const { jsPDF } = window.jspdf;
      const doc = new jsPDF({ orientation:'landscape', unit:'mm', format:'a4' });

      doc.setFont('helvetica','bold'); doc.setFontSize(14);
      doc.text('REKAP ABSENSI & NILAI', doc.internal.pageSize.getWidth()/2, 16, {align:'center'});
      doc.setFont('helvetica','normal'); doc.setFontSize(10.5);
      doc.text(`KELAS : ${r.kelasNama}`, doc.internal.pageSize.getWidth()/2, 22, {align:'center'});

      const head = [['No','Nama','Hadir','S','I','A','% Hadir', ...TP_LIST, 'Rata-rata']];
      const body = r.siswaList.map((s,i) => {
        const rh = r.rekapHadir[s.id];
        const pct = r.jumlahPertemuan ? Math.round((rh.H/r.jumlahPertemuan)*100) : 0;
        const nilaiSiswa = r.nilaiMap[s.id] || {};
        let total = 0, count = 0;
        const kolomTp = TP_LIST.map(tp => {
          const v = nilaiSiswa[tp];
          if(v !== undefined && v !== null){ total += Number(v); count++; return String(v); }
          return '-';
        });
        const rataRata = count ? String(Math.round(total/count)) : '-';
        return [String(i+1), s.nama, String(rh.H), String(rh.S), String(rh.I), String(rh.A), pct+'%', ...kolomTp, rataRata];
      });

      doc.autoTable({
        head, body, startY: 28,
        theme: 'grid',
        styles: { font:'helvetica', fontSize:8, cellPadding:2, valign:'middle' },
        headStyles: { fillColor:[15,54,39], textColor:255, fontStyle:'bold', halign:'center' },
        bodyStyles: { halign:'center' },
        columnStyles: { 1: { halign:'left', cellWidth: 46 } },
        alternateRowStyles: { fillColor:[242,247,244] },
        margin: { left:14, right:14 }
      });

      let finalY = doc.lastAutoTable.finalY + 12;
      tambahBlokTandaTangan(doc, finalY);

      doc.save(`rekap-${namaFileAman(r.kelasNama)}.pdf`);
    } catch(err){
      alert('Gagal membuat PDF: ' + err.message);
    } finally {
      if(btn){ btn.disabled = false; btn.textContent = 'Download PDF'; }
    }
  }

  // ---------------- PDF: Jurnal Guru ----------------
  async function generatePdfJurnal(){
    const j = state.lastJurnal;
    if(!j || !j.rows.length){ alert('Belum ada data jurnal bulan ini untuk didownload.'); return; }
    const btn = document.getElementById('btnDownloadJurnalPdf');
    if(btn){ btn.disabled = true; btn.textContent = 'Menyiapkan PDF…'; }
    try{
      await pastikanJsPDF();
      const { jsPDF } = window.jspdf;
      const orientasiSelect = document.getElementById('selectOrientasiJurnal');
      const orientasi = orientasiSelect && orientasiSelect.value === 'portrait' ? 'portrait' : 'landscape';
      const doc = new jsPDF({ orientation: orientasi === 'portrait' ? 'p' : 'l', unit:'mm', format:'a4' });

      doc.setFont('helvetica','bold'); doc.setFontSize(13);
      doc.text('AGENDA DAN JURNAL KEGIATAN GURU', doc.internal.pageSize.getWidth()/2, 15, {align:'center'});
      doc.setFont('helvetica','normal'); doc.setFontSize(10.5);
      doc.text(`BULAN : ${BULAN_NAMA[j.bulanNum]} ${j.tahun}`, doc.internal.pageSize.getWidth()/2, 21, {align:'center'});

      const head = [['Hari/Tgl','Pukul','Kelas/Tempat','1. Kegiatan Guru','2. No.KD/Materi Pelajaran','3. Indikator Kompetensi','Nama Siswa Tidak Hadir','S','I','A','Keterangan/Output Kegiatan']];
      const body = j.rows.map(r => [
        bersihkanTeksPdf(r.tanggal),
        bersihkanTeksPdf(r.pukul),
        bersihkanTeksPdf(r.tempat),
        bersihkanTeksPdf(r.kegiatan) || '-',
        bersihkanTeksPdf(r.materi) || '-',
        bersihkanTeksPdf(r.indikator) || '-',
        bersihkanTeksPdf(r.siswaTidakHadir) || '-',
        String(r.s || 0), String(r.i || 0), String(r.a || 0),
        bersihkanTeksPdf(r.keterangan) || '-'
      ]);

      doc.autoTable({
        head, body, startY: 26,
        theme: 'grid',
        styles: { font:'helvetica', fontSize: 7.2, cellPadding:1.8, valign:'top', overflow:'linebreak' },
        headStyles: { fillColor:[15,54,39], textColor:255, fontStyle:'bold', fontSize:7.6, halign:'center' },
        alternateRowStyles: { fillColor:[242,247,244] },
        columnStyles: {
          0: { cellWidth: 20, halign:'center' },
          1: { cellWidth: 20, halign:'center' },
          2: { cellWidth: 18, halign:'center' },
          7: { cellWidth: 7, halign:'center' },
          8: { cellWidth: 7, halign:'center' },
          9: { cellWidth: 7, halign:'center' }
        },
        margin: { left:12, right:12 }
      });

      let finalY = doc.lastAutoTable.finalY + 14;
      tambahBlokTandaTangan(doc, finalY);

      doc.save(`jurnal-guru-${BULAN_NAMA[j.bulanNum]}-${j.tahun}.pdf`);
    } catch(err){
      alert('Gagal membuat PDF: ' + err.message);
    } finally {
      if(btn){ btn.disabled = false; btn.textContent = 'Download PDF'; }
    }
  }

  // ---------------- Pasang tombol "Download PDF" di sebelah tombol Excel yang sudah ada ----------------
  function pasangTombolPdf(){
    const btnExcelRekap = document.getElementById('btnDownloadRekap');
    if(btnExcelRekap && !document.getElementById('btnDownloadRekapPdf')){
      const btnPdf = document.createElement('button');
      btnPdf.id = 'btnDownloadRekapPdf';
      btnPdf.className = 'btn btn-outline btn-sm';
      btnPdf.type = 'button';
      btnPdf.style.marginLeft = '8px';
      btnPdf.textContent = 'Download PDF';
      btnPdf.addEventListener('click', generatePdfRekap);
      btnExcelRekap.insertAdjacentElement('afterend', btnPdf);
    }

    const btnExcelJurnal = document.getElementById('btnDownloadJurnal');
    if(btnExcelJurnal && !document.getElementById('btnDownloadJurnalPdf')){
      const btnPdf2 = document.createElement('button');
      btnPdf2.id = 'btnDownloadJurnalPdf';
      btnPdf2.className = 'btn btn-outline btn-sm';
      btnPdf2.type = 'button';
      btnPdf2.style.marginLeft = '8px';
      btnPdf2.textContent = 'Download PDF';
      btnPdf2.addEventListener('click', generatePdfJurnal);
      btnExcelJurnal.insertAdjacentElement('afterend', btnPdf2);
    }
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', pasangTombolPdf);
  } else {
    pasangTombolPdf();
  }
})();
